// Тикеты #6a86f7eda7b2 «פיתוח: האזנה להקראת התפילה» (F-91) и #6a86f7ed9d38 «פיתוח: אספקת הקלטות הקראה» (F-92), проверены на web 07.10.2026.
// Опора: F-91 AC4 «כאשר אין הקלטה לטקסט מסוים, פעולת ההשמעה אינה מוצגת כזמינה»; F-92 AC1 «היעדר הקלטה לפריט מסומן במפורש ואינו מוצג ככשל».
// Факт 07.10: ערבית (אשכנזי) קטע 2 и 5 из 15 — без записи (скрины rec-D4-user-s2-no-recording, pg-5-p5-no-recording).
import { expect } from '@wdio/globals';
import { byText, expectVisibleText, scrollToText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { ensureNusach, playerButton, recordingLine } from '../_lib/app-0710.ts';

describe('Озвучка: страница без записи', () => {
  afterEach(async () => { await toHome(); });

  it('RC-01 קטע без записи: «אין הקראה לקטע הזה», «השמע» неактивна, строки «הקראה:» нет #6a86f7eda7b2 #6a86f7ed9d38 @prod-safe', async () => {
    await openPrayer('arvit_ashkenaz', 'ערבית');
    await ensureNusach('אשכנזי');

    for (const page of [2, 5]) {
      await goToPage(page, 15);
      expect(await pageCounter()).toBe(`${page} מתוך 15`);
      await scrollToText('האזן להקראה');
      await expectVisibleText('אין הקראה לקטע הזה');
      await expect(await playerButton('השמע')).toBeDisabled();
      await expect(recordingLine()).not.toBeDisplayed();
      // Без автозапуска и без «мёртвого» плеера: кнопки «השהה» нет.
      await expect(byText('השהה')).not.toBeDisplayed();
    }
  });
});
